import React, { useState } from "react";
import { motion } from "framer-motion";
import {
  Droplets,
  AlertTriangle,
  CheckCircle,
  Clock,
  MapPin,
  Phone,
  Plus,
  Filter,
  Search,
} from "lucide-react";
import Notifications from "../components/common/Notifications";

const HospitalDashboard = () => {
  const [activeTab, setActiveTab] = useState("overview");
  const [inventoryFilter, setInventoryFilter] = useState("all");

  // Mock data for blood inventory
  const bloodInventory = [
    { type: "A+", quantity: 15, status: "available", expiry: "2024-03-15" },
    { type: "A-", quantity: 8, status: "low", expiry: "2024-03-10" },
    { type: "B+", quantity: 12, status: "available", expiry: "2024-03-18" },
    { type: "B-", quantity: 3, status: "critical", expiry: "2024-03-05" },
    { type: "AB+", quantity: 7, status: "available", expiry: "2024-03-12" },
    { type: "AB-", quantity: 2, status: "critical", expiry: "2024-03-03" },
    { type: "O+", quantity: 20, status: "available", expiry: "2024-03-20" },
    { type: "O-", quantity: 18, status: "available", expiry: "2024-03-19" },
  ];

  // Mock data for emergency requests
  const emergencyRequests = [
    {
      id: 1,
      patient: "John Doe",
      bloodType: "B-",
      quantity: 2,
      status: "new",
      priority: "high",
      time: "2 min ago",
    },
    {
      id: 2,
      patient: "Jane Smith",
      bloodType: "O+",
      quantity: 1,
      status: "matching",
      priority: "medium",
      time: "15 min ago",
    },
    {
      id: 3,
      patient: "Robert Johnson",
      bloodType: "AB+",
      quantity: 3,
      status: "fulfilled",
      priority: "low",
      time: "1 hour ago",
    },
  ];

  // Mock data for nearby hospitals
  const nearbyHospitals = [
    {
      id: 1,
      name: "City General Hospital",
      distance: "2.5 km",
      bloodTypes: ["O+", "B+"],
      status: "available",
    },
    {
      id: 2,
      name: "St. Mary Medical Center",
      distance: "4.2 km",
      bloodTypes: ["A+", "O-"],
      status: "limited",
    },
    {
      id: 3,
      name: "Regional Blood Bank",
      distance: "6.8 km",
      bloodTypes: ["A-", "B-", "AB+"],
      status: "available",
    },
  ];

  const getStatusColor = (status) => {
    switch (status) {
      case "available":
        return "text-green-400 bg-green-500/20 border border-green-500/30";
      case "low":
        return "text-yellow-400 bg-yellow-500/20 border border-yellow-500/30";
      case "critical":
        return "text-red-400 bg-red-500/20 border border-red-500/30";
      case "new":
        return "text-blue-400 bg-blue-500/20 border border-blue-500/30";
      case "matching":
        return "text-yellow-400 bg-yellow-500/20 border border-yellow-500/30";
      case "fulfilled":
        return "text-green-400 bg-green-500/20 border border-green-500/30";
      default:
        return "text-gray-400 bg-gray-500/20 border border-gray-500/30";
    }
  };

  const filteredInventory =
    inventoryFilter === "all"
      ? bloodInventory
      : bloodInventory.filter((item) => item.status === inventoryFilter);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: { duration: 0.5 },
    },
  };

  return (
    <div className="min-h-screen bg-gray-900">
      {/* Notifications */}
      <div className="fixed top-4 right-4 z-50">
        <Notifications />
      </div>

      {/* Header */}
      <motion.header
        initial={{ y: -100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="glass-card m-6 rounded-2xl p-6 shadow-xl"
      >
        <div className="flex flex-col md:flex-row md:items-center md:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white">
              Hospital Dashboard
            </h1>
            <p className="text-gray-300">Welcome back, Dr. Anderson</p>
          </div>
          <div className="mt-4 md:mt-0 flex items-center space-x-4">
            <div className="text-right">
              <p className="text-white font-medium">City General Hospital</p>
              <p className="text-gray-400 text-sm">New York, NY</p>
            </div>
            <div className="w-12 h-12 bg-red-500 rounded-full flex items-center justify-center">
              <Droplets className="w-6 h-6 text-white" />
            </div>
          </div>
        </div>
      </motion.header>

      {/* Navigation Tabs */}
      <motion.nav
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.1 }}
        className="mx-6 mb-6"
      >
        <div className="flex space-x-1 glass-card p-2 rounded-2xl">
          {["overview", "inventory", "requests", "exchange"].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 py-3 px-4 rounded-xl font-medium transition-all duration-200 ${
                activeTab === tab
                  ? "bg-red-600 text-white shadow-lg"
                  : "text-gray-300 hover:text-white hover:bg-white/10"
              }`}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)}
            </button>
          ))}
        </div>
      </motion.nav>

      <motion.main
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="mx-6 mb-6"
      >
        {/* Overview Tab */}
        {activeTab === "overview" && (
          <>
            {/* Stats Cards */}
            <motion.div
              variants={itemVariants}
              className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8"
            >
              <div className="glass-card p-6 rounded-2xl">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400">Total Units</p>
                    <p className="text-3xl font-bold text-white">87</p>
                  </div>
                  <div className="w-12 h-12 bg-red-500/20 rounded-full flex items-center justify-center">
                    <Droplets className="w-6 h-6 text-red-400" />
                  </div>
                </div>
              </div>

              <div className="glass-card p-6 rounded-2xl">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400">Low Stock</p>
                    <p className="text-3xl font-bold text-yellow-400">2</p>
                  </div>
                  <div className="w-12 h-12 bg-yellow-500/20 rounded-full flex items-center justify-center">
                    <AlertTriangle className="w-6 h-6 text-yellow-400" />
                  </div>
                </div>
              </div>

              <div className="glass-card p-6 rounded-2xl">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400">Critical Levels</p>
                    <p className="text-3xl font-bold text-red-400">2</p>
                  </div>
                  <div className="w-12 h-12 bg-red-500/20 rounded-full flex items-center justify-center">
                    <AlertTriangle className="w-6 h-6 text-red-400" />
                  </div>
                </div>
              </div>

              <div className="glass-card p-6 rounded-2xl">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400">Active Requests</p>
                    <p className="text-3xl font-bold text-blue-400">3</p>
                  </div>
                  <div className="w-12 h-12 bg-blue-500/20 rounded-full flex items-center justify-center">
                    <CheckCircle className="w-6 h-6 text-blue-400" />
                  </div>
                </div>
              </div>
            </motion.div>

            {/* Blood Type Cards */}
            <motion.div
              variants={itemVariants}
              className="glass-card p-6 rounded-2xl mb-8"
            >
              <h2 className="text-2xl font-bold text-white mb-6">
                Blood Inventory Overview
              </h2>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-4">
                {bloodInventory.map((item, index) => (
                  <motion.div
                    key={index}
                    whileHover={{ scale: 1.05 }}
                    className="blood-type-card"
                  >
                    <div className="text-center">
                      <div className="text-2xl font-bold text-white mb-2">
                        {item.type}
                      </div>
                      <div
                        className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(
                          item.status
                        )}`}
                      >
                        {item.quantity} units
                      </div>
                      <div className="text-xs text-gray-400 mt-2">
                        Exp: {item.expiry.split("-")[1]}/
                        {item.expiry.split("-")[2]}
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>

            {/* Near Expiry Warning */}
            <motion.div
              variants={itemVariants}
              className="glass-card p-6 rounded-2xl"
            >
              <h2 className="text-2xl font-bold text-white mb-6">
                Near Expiry Alerts
              </h2>
              <div className="space-y-4">
                {bloodInventory
                  .filter((item) => item.status !== "available")
                  .map((item, index) => (
                    <div
                      key={index}
                      className="flex items-center justify-between p-4 rounded-xl bg-red-500/10 border border-red-500/20"
                    >
                      <div className="flex items-center">
                        <AlertTriangle className="w-5 h-5 text-red-400 mr-3" />
                        <span className="text-white font-medium">
                          {item.type}
                        </span>
                      </div>
                      <div className="text-right">
                        <div
                          className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(
                            item.status
                          )}`}
                        >
                          {item.quantity} units
                        </div>
                        <div className="text-xs text-gray-400 mt-1">
                          Expires: {item.expiry}
                        </div>
                      </div>
                    </div>
                  ))}
              </div>
            </motion.div>
          </>
        )}

        {/* Inventory Tab */}
        {activeTab === "inventory" && (
          <motion.div
            variants={itemVariants}
            className="glass-card p-6 rounded-2xl"
          >
            <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
              <h2 className="text-2xl font-bold text-white mb-4 md:mb-0">
                Blood Inventory
              </h2>
              <div className="flex space-x-4">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <input
                    type="text"
                    placeholder="Search inventory..."
                    className="pl-10 pr-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-red-500"
                  />
                </div>
                <select
                  value={inventoryFilter}
                  onChange={(e) => setInventoryFilter(e.target.value)}
                  className="px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-red-500"
                >
                  <option value="all">All Status</option>
                  <option value="available">Available</option>
                  <option value="low">Low</option>
                  <option value="critical">Critical</option>
                </select>
                <button className="flex items-center space-x-2 bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg transition-colors">
                  <Plus className="w-4 h-4" />
                  <span>Add Unit</span>
                </button>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-gray-700">
                    <th className="text-left py-3 text-gray-300">Blood Type</th>
                    <th className="text-left py-3 text-gray-300">Quantity</th>
                    <th className="text-left py-3 text-gray-300">Status</th>
                    <th className="text-left py-3 text-gray-300">
                      Expiry Date
                    </th>
                    <th className="text-left py-3 text-gray-300">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredInventory.map((item, index) => (
                    <motion.tr
                      key={index}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.1 }}
                      className="border-b border-gray-800 hover:bg-white/5 transition-colors"
                    >
                      <td className="py-4">
                        <div className="font-medium text-white">
                          {item.type}
                        </div>
                      </td>
                      <td className="py-4">
                        <div className="text-white">{item.quantity} units</div>
                      </td>
                      <td className="py-4">
                        <span
                          className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(
                            item.status
                          )}`}
                        >
                          {item.status.charAt(0).toUpperCase() +
                            item.status.slice(1)}
                        </span>
                      </td>
                      <td className="py-4">
                        <div className="text-gray-300">{item.expiry}</div>
                      </td>
                      <td className="py-4">
                        <button className="text-red-400 hover:text-red-300 mr-3">
                          Edit
                        </button>
                        <button className="text-gray-400 hover:text-white">
                          Delete
                        </button>
                      </td>
                    </motion.tr>
                  ))}
                </tbody>
              </table>
            </div>
          </motion.div>
        )}

        {/* Requests Tab */}
        {activeTab === "requests" && (
          <motion.div variants={itemVariants} className="space-y-6">
            <div className="glass-card p-6 rounded-2xl">
              <h2 className="text-2xl font-bold text-white mb-6">
                Emergency Requests
              </h2>
              <div className="space-y-4">
                {emergencyRequests.map((request, index) => (
                  <motion.div
                    key={request.id}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: index * 0.1 }}
                    className="p-6 glass-card rounded-xl"
                  >
                    <div className="flex flex-col md:flex-row md:items-center md:justify-between">
                      <div className="flex-1">
                        <div className="flex items-center mb-2">
                          <span
                            className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(
                              request.status
                            )}`}
                          >
                            {request.status.charAt(0).toUpperCase() +
                              request.status.slice(1)}
                          </span>
                          <span
                            className={`ml-3 px-3 py-1 rounded-full text-xs font-medium ${
                              request.priority === "high"
                                ? "text-red-400 bg-red-500/20"
                                : request.priority === "medium"
                                ? "text-yellow-400 bg-yellow-500/20"
                                : "text-green-400 bg-green-500/20"
                            }`}
                          >
                            {request.priority.charAt(0).toUpperCase() +
                              request.priority.slice(1)}{" "}
                            Priority
                          </span>
                        </div>
                        <h3 className="text-lg font-semibold text-white">
                          {request.patient}
                        </h3>
                        <div className="flex items-center text-gray-300 mt-2">
                          <Droplets className="w-4 h-4 mr-2" />
                          <span>Blood Type: {request.bloodType}</span>
                          <span className="mx-2">•</span>
                          <span>
                            {request.quantity} unit
                            {request.quantity > 1 ? "s" : ""}
                          </span>
                          <span className="mx-2">•</span>
                          <span>{request.time}</span>
                        </div>
                      </div>
                      <div className="mt-4 md:mt-0 flex space-x-3">
                        <button className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg transition-colors">
                          View Details
                        </button>
                        <button className="px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg transition-colors">
                          Contact
                        </button>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        )}

        {/* Exchange Tab */}
        {activeTab === "exchange" && (
          <motion.div
            variants={itemVariants}
            className="glass-card p-6 rounded-2xl"
          >
            <h2 className="text-2xl font-bold text-white mb-6">
              Hospital Exchange
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {nearbyHospitals.map((hospital, index) => (
                <motion.div
                  key={hospital.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.1 }}
                  className="p-6 glass-card rounded-2xl"
                >
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-semibold text-white">
                      {hospital.name}
                    </h3>
                    <span
                      className={`px-3 py-1 rounded-full text-xs font-medium ${
                        hospital.status === "available"
                          ? "text-green-400 bg-green-500/20"
                          : hospital.status === "limited"
                          ? "text-yellow-400 bg-yellow-500/20"
                          : "text-red-400 bg-red-500/20"
                      }`}
                    >
                      {hospital.status.charAt(0).toUpperCase() +
                        hospital.status.slice(1)}
                    </span>
                  </div>
                  <div className="flex items-center text-gray-300 mb-4">
                    <MapPin className="w-4 h-4 mr-2" />
                    <span>{hospital.distance}</span>
                  </div>
                  <div className="mb-4">
                    <p className="text-sm text-gray-400 mb-2">
                      Available Blood Types:
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {hospital.bloodTypes.map((type, idx) => (
                        <span
                          key={idx}
                          className="px-2 py-1 bg-gray-800 text-white text-xs rounded"
                        >
                          {type}
                        </span>
                      ))}
                    </div>
                  </div>
                  <div className="flex space-x-2">
                    <button className="flex-1 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg transition-colors flex items-center justify-center">
                      <Phone className="w-4 h-4 mr-2" />
                      Request
                    </button>
                    <button className="flex-1 px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg transition-colors">
                      Offer
                    </button>
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>
        )}
      </motion.main>
    </div>
  );
};

export default HospitalDashboard;
